    "year": "1998-2007",
    "sample_size": "49 neonates who received pentazocine",
    "follow_up": null
  },
  "population": {
    "age": "mean 12 days (SD 1.2); range 9 hours to 28 days",
    "age_criteria": "neonates; reported age range among deaths was 9 hours to 28 days",
    "sex": null,
    "weight": null,
    "key_characteristics": "surgical neonates; 49 of 368 neonates (13.3%) received pentazocine; 15 deaths (30.6%); 56 neonates developed respiratory depression, of whom 40 (71.4%) had pentazocine"
  },
  "intervention": {
    "name": "pentazocine",
    "dose": "0.5 mg/kg",
    "frequency": "8-hourly",
    "duration": null
  },
  "outcomes": [
    {
      "measure": "mortality",
      "timepoint": "between 1 and 36 hours after 8-hourly administration of pentazocine",
      "effect": "15/49 (30.6%)",
      "ci": null
    },
    {
      "measure": "respiratory depression",
      "timepoint": null,
      "effect": "40/56 (71.4%) of neonates who developed respiratory depression had received pentazocine; p<0.0001",
      "ci": null
    }
  ],
  "safety": [
    {
      "event": "respiratory depression",
      "rate": "40/56 (71.4%) of neonates with respiratory depression had received pentazocine; p<0.0001"
    },
    {
      "event": "death",
      "rate": "15/49 (30.6%)"
    },
    {
      "event": "over-sedation",
      "rate": "reported as a problem in older children; no deaths"
    }
  ],
  "other_facts": "In developing countries, neonatal analgesia for surgical procedures is a major challenge where postoperative care is inadequate. The study reported experience of pentazocine for neonatal surgery at the University of Benin Teaching Hospital, Benin City, Nigeria, between January 1998 and December 2007. During the period, 2590 paediatric operations were performed, including 368 neonates (14.2%); 49 of these neonates (13.3%) received pentazocine, and other neonates received a variety of analgesics. Of 56 neonates who developed respiratory depression, 40 (71.4%) had pentazocine (p<0.0001). Fifteen (30.6%) neonates aged between 9 hours and 28 days [mean (SD) 12 (1.2) days] died between 1 and 36 hours following 8-hourly administration of 0.5 mg/kg pentazocine. In older children who had pentazocine, over-sedation was a problem but there were no deaths. Deaths in neonates were mainly owing to persistent respiratory depression compounded by unavailability of a paediatric ventilator; many neonates responded to naloxone. All neonates who died had an autopsy and no lesion was found that could have compromised respiratory function. The use of pentazocine in neonates was associated with high morbidity and mortality; caution is required when using pentazocine for neonatal analgesia where post-operative respiratory support is insufficient.",
  "summary": "In a retrospective study of surgical neonates in Nigeria, pentazocine 0.5 mg/kg given every 8 hours was associated with frequent respiratory depression and 30.6% mortality, especially where postoperative respiratory support was limited."
}

