    "key_characteristics": "Adult trauma patients at a single Level I Trauma Center who met criteria for full trauma team activation and had an arterial cannula inserted; blood was sampled a median of 68 minutes (IQR 48 to 88) post-injury; data on demography, biochemistry, injury severity score and mortality were recorded."
  },
  "intervention": {
    "name": null,
    "dose": null,
    "frequency": null,
    "duration": null
  },
  "outcomes": [
    {
      "measure": "Overt DIC prevalence",
      "timepoint": "median 68 minutes (IQR 48 to 88) post-injury",
      "effect": "0%",
      "ci": null
    },
    {
