{
  "study": {
    "design": "Population pharmacokinetic/pharmacodynamic modelling and simulation study using pooled data from two previous studies; randomized clinical trial planned/ongoing",
    "year": null,
    "sample_size": "273 patients with paclitaxel plasma concentration-time data; 152 of the 273 patients with absolute neutrophil count data; simulated datasets of 1000 patients",
    "follow_up": "Six subsequent treatment cycles in simulations"
  },
  "population": {
    "age": null,
    "age_criteria": null,
    "sex": "Male and female patients included; no numerical sex distribution reported",
    "weight": null,
    "key_characteristics": "Patient age, sex, body surface area, bilirubin and renal function were tested as potential covariates on paclitaxel maximum elimination capacity; age, sex, bilirubin and body surface area were significant and independent covariates on paclitaxel elimination; paclitaxel maximum elimination capacity was 16% higher in males than in females; a 10-year increase in age led to a 13% decrease in paclitaxel maximum elimination capacity; the ongoing randomized trial is in patients with advanced non-small cell lung cancer"
  },
  "intervention": {
    "name": "Personalized pharmacology-driven paclitaxel dosing algorithm; comparator: conventional body surface area-based paclitaxel dosing",
    "dose": "Personalized first-cycle paclitaxel dose 150-185 mg/m2 for women and 165-200 mg/m2 for men; dose adaptations for cycles 2-6 ranged from -40% to +30%; final median paclitaxel dose 167 mg/m2, range 76-311 mg/m2; conventional comparator dose 200 mg/m2",
    "frequency": "Every 3 weeks",
    "duration": "Six treatment cycles"
  },
  "outcomes": [
    {
      "measure": "Grade 4 neutropenia",
      "timepoint": "Cycle 1",
      "effect": "Reduced from 15% with conventional dosing to 7% with personalized dosing",
      "ci": null
    },
    {
      "measure": "Grade 4 neutropenia",
      "timepoint": "Cycle 2",
      "effect": "4% with personalized dosing",
      "ci": null
    },
    {
      "measure": "Prediction of paclitaxel T(C>0.05) using a single plasma concentration",
      "timepoint": "24 hours after start of infusion",
      "effect": "Root squared mean error +0.5%",
      "ci": null
    },
    {
      "measure": "Prediction of paclitaxel T(C>0.05) with addition of an end-of-infusion sample",
      "timepoint": "End of infusion plus 24 hours after start of infusion",
      "effect": "Root squared mean error -0.6%",
      "ci": null
    }
  ],
  "safety": [
    {
      "event": "Grade 4 neutropenia",
      "rate": "15% with conventional paclitaxel 200 mg/m2 in cycle 1"
    },
    {
      "event": "Grade 4 neutropenia",
      "rate": "7% with personalized dosing in cycle 1"
    },
    {
      "event": "Grade 4 neutropenia",
      "rate": "4% with personalized dosing in cycle 2"
    }
  ],
  "other_facts": "Severe neutropenia is the most frequent and important toxicity of 3-weekly paclitaxel and puts patients at substantial risk of infectious complications. The time during which paclitaxel plasma concentrations exceed 0.05 μmol/L, T(C>0.05), correlates with the extent of neutropenia. The dosing algorithm targeted an individual paclitaxel T(C>0.05) between 26 and 31 hours. Paclitaxel plasma concentration-time data and absolute neutrophil count data were pooled from two previous studies. Population pharmacokinetic and pharmacodynamic modelling was performed using NONMEM version VII. A previously described 3-compartment model with saturable elimination and distribution was coupled to a semiphysiological model with a linear function describing the myelotoxic effect of paclitaxel on circulating neutrophils. Paclitaxel concentration-time data were adequately described by the 3-compartment model. Individual absolute neutrophil counts were adequately described by the semiphysiological model. Limited sampling strategies were tested for accuracy in predicting paclitaxel T(C>0.05). The first-cycle dosing algorithm accounted for body surface area, patient age and sex. Later cycles accounted for previous-cycle paclitaxel T(C>0.05), target 26-31 hours, and absolute neutrophil count nadir to adapt the next paclitaxel dose. Extensive simulations from the final pharmacokinetic/pharmacodynamic model generated datasets of 1000 patients for six subsequent treatment cycles. Grade 4 neutropenia was tested as a potential endpoint for a prospective clinical trial. A randomized clinical trial comparing this dosing algorithm with conventional body surface area-based paclitaxel dosing in patients with advanced non-small cell lung cancer is currently ongoing.",
  "summary": "A population pharmacokinetic/pharmacodynamic modelling and simulation study developed a personalized 3-weekly paclitaxel dosing algorithm targeting T(C>0.05) of 26-31 hours, which reduced simulated grade 4 neutropenia compared with conventional 200 mg/m2 dosing and is being evaluated in an ongoing randomized trial in advanced non-small cell lung cancer."
}

